const fresh=()=>({points:0,claims:[],completions:[],orders:[]});let state;try{state=JSON.parse(localStorage.getItem('wearquest-v1'))||fresh();if(!Array.isArray(state.claims)||!Array.isArray(state.completions)||!Array.isArray(state.orders))state=fresh()}catch{state=fresh()}
if(!Array.isArray(state.cart))state.cart=[];let route='home',filter='전체',activeGame=null,round=0,sessionToken=0,timer=null;const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const completedToday=()=>state.completions.filter(c=>c.date===today());const steps=()=>[completedToday().length>=1,new Set(completedToday().map(c=>c.id)).size>=2,completedToday().length>=3];const claimed=()=>state.claims.includes(today());const save=()=>{try{localStorage.setItem('wearquest-v1',JSON.stringify(state))}catch{toast('저장 공간이 부족해 진행 상황을 저장하지 못했어요.')}};const svg=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[k]}</svg>`;const ad=()=>'<aside class="ad-slot" aria-label="광고 영역"><span>ADVERTISEMENT</span><span>광고 영역</span><small>AD</small></aside>';
function toast(t){const x=document.getElementById('toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2800)}
function go(r){clearInterval(timer);sessionToken++;activeGame=null;if(!['home','games','shop','my','login','signup','other-login','account','terms','privacy'].includes(r)&&!/^product-[0-5]$/.test(r))r='home';location.hash=r;route=r;render();window.scrollTo(0,0)}window.addEventListener('hashchange',()=>{clearInterval(timer);sessionToken++;route=location.hash.slice(1)||'home';if(route!=='play')activeGame=null;render()});
const gameIllustrations=Array.from({length:20},(_,i)=>'game-illustration-'+String(i+1).padStart(2,'0')+'.webp');
function gameCard(g,i){return `<button class="game" onclick="startGame(${i})"><div class="game-art" style="--tone:${g[6]}"><span class="tag">${g[4].toUpperCase()}</span><img class="game-photo" loading="lazy" decoding="async" src="${gameIllustrations[i]}" alt="${g[0]} 패션 일러스트" style="object-position:center"><span class="game-index">NO. ${String(i+1).padStart(2,'0')}</span><span class="game-arrow">↗</span></div><div class="game-info"><h3>${g[0]}</h3><p>${g[1]}</p><footer><span>약 1분</span><b>${completedToday().some(c=>c.id===i)?'완료 ✓':'PLAY'}</b></footer></div></button>`}
function startQuest(index){const status=steps();if(status[index])return toast('이미 완료한 미션이에요. 다른 미션에 도전해주세요.');const played=new Set(completedToday().map(c=>c.id));const next=games.findIndex((g,i)=>!played.has(i));startGame(index===0?0:(next<0?0:next))}
function questAction(){if(claimed())return toast('오늘은 이미 1P를 적립했어요.');const next=steps().findIndex(done=>!done);if(next<0)claim();else startQuest(next)}
function questUI(){const s=steps();return `<section class="section"><div class="section-title"><h2>오늘의 미션 <span class="sub">${s.filter(Boolean).length}/3</span></h2><span class="badge">매일 새로 시작</span></div><div class="quests">${[['첫 번째 플레이','게임 1회 클리어'],['다른 게임도 도전','서로 다른 게임 2종 클리어'],['오늘의 플레이 완성','게임 총 3회 클리어']].map((q,i)=>`<button type="button" class="quest ${s[i]?'done':''}" onclick="startQuest(${i})" aria-label="${q[0]} ${s[i]?'완료 확인':'시작'}"><span class="num">${s[i]?'✓':'0'+(i+1)}</span><span class="quest-copy"><span class="quest-title">${q[0]}</span><span class="quest-description">${q[1]}</span></span><span class="end">${s[i]?'완료':'시작 ›'}</span></button>`).join('')}</div><div class="reward-line"><span>✳ 미션 3개 완료 시 <b>1P 자동 적립</b></span><button type="button" onclick="questAction()">${claimed()?'오늘 적립 완료':s.every(Boolean)?'1P 받기':'미션 시작'}</button></div></section>`}
function calendar(){return `<div class="days">${Array.from({length:30},(_,i)=>`<span class="day ${i<state.claims.length?'checked':''}">${i<state.claims.length?'✓':i===29?'30P':i+1}</span>`).join('')}</div>`}
function homePointSummary(){const earned=claimed(),done=steps().filter(Boolean).length,points=state.points,remaining=Math.max(0,30-points),fill=Math.min(100,points/30*100);return `<div class="reward-heading"><h1>포인트 모아, 옷 한 벌.</h1></div><section class="purchase-progress"><div class="between"><h2>내 포인트</h2><button class="text-button" onclick="go('my')">적립 내역 ↗</button></div><div class="purchase-balance"><strong>${points}<small>P</small></strong><span>구매 목표 <b>30P</b></span></div><div class="purchase-gauge" role="progressbar" aria-label="30P 옷 구매 목표 진행률" aria-valuemin="0" aria-valuemax="30" aria-valuenow="${Math.min(points,30)}" aria-valuetext="${points}P 보유, 구매까지 ${remaining}P 남음"><span class="gauge-earned" style="width:${fill}%"></span></div><div class="gauge-labels"><span>0P</span><b>30P · 옷 구매</b></div><div class="purchase-message">${remaining?`옷 한 벌까지 <b>${remaining}P</b> 남았어요.`:'목표 달성! <b>옷을 고를 수 있어요.</b>'}</div><p class="goal-days">${remaining?`하루 1P씩, ${remaining}일 더 참여하면 돼요.`:'포인트몰에서 마음에 드는 상품을 골라보세요.'}</p><div class="daily-inline"><span>${earned?'오늘 <b>1P 적립 완료 ✓</b>':'오늘 받을 포인트 <b>+1P</b>'}</span><span>${earned?'내일 다시 만나요':`미션 ${done}/3 완료`}</span></div><button class="primary full home-main-action" onclick="${earned?"go('shop')":"questAction()"}">${earned?'포인트몰 둘러보기 ↗':done===3?'오늘의 1P 받기':done?'이어서 1P 모으기 ↗':'오늘의 1P 모으기 ↗'}</button></section>`}
function home(){const done=steps().filter(Boolean).length,earned=claimed();return `${ad()}${homePointSummary()}<aside class="home-ad-banner" aria-label="홈 배너 광고"><span>ADVERTISEMENT</span><b>광고 배너 영역</b><small>광고 연결 준비 중</small><i aria-hidden="true">AD</i></aside><section class="section"><div class="section-title"><div><h2>게임하기</h2></div><button class="text-button" onclick="go('games')">게임 20개 ↗</button></div><div class="games">${games.slice(0,2).map(gameCard).join('')}</div></section><section class="section home-shop"><div class="section-title"><div><h2>포인트몰</h2></div><button class="text-button" onclick="go('shop')">전체 보기 ↗</button></div><div class="products">${products.slice(0,4).map((p,i)=>`<article class="product"><button class="product-art" onclick="productDetail(${i})" aria-label="${p[0]} 상세 보기"><img loading="lazy" src="${productImage(i)}" alt="${p[0]} 샘플 이미지"></button><div class="body"><span class="eyebrow">WEAR QUEST</span><h3>${p[0]}</h3><p class="sub">${p[1]}</p><div class="between"><b>30 P</b></div><button class="primary" onclick="productDetail(${i})">상품 보기 ↗</button></div></article>`).join('')}</div><p class="footnote">샘플 상품 · 주문일로부터 30일 후 수령 예정<br>실제 주문·배송은 연결 전입니다.</p></section>`}
function gamePage(){return `${ad()}<div class="intro"><div><h1>게임하기</h1><p class="sub">20개의 패션 게임 · 플레이 횟수는 자유롭게, 적립은 하루 1P</p></div><span class="badge">${state.completions.length}회 클리어</span></div>${questUI()}<div class="chips">${['전체','스타일','기억력','컬러','상식','관찰','순발력'].map(x=>`<button class="${filter===x?'active':''}" onclick="filter='${x}';render()">${x}</button>`).join('')}</div><div class="games">${games.map((g,i)=>filter==='전체'||g[4]===filter?gameCard(g,i):'').join('')}</div>`}
const productPhotos=['product-tee.jpg','product-denim.jpg','product-cap.jpg','product-vest.jpg','product-shirt.jpg','product-hoodie.jpg'];
function productImage(i){return productPhotos[i]||'fashion.jpg'}
const shopCategories=['전체','아우터','바지','반팔티','긴팔티','양말','기타'];
const productCategories=['반팔티','바지','기타','아우터','긴팔티','긴팔티'];
let shopCategory='전체',shopQuery='';
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function filteredProducts(){const query=shopQuery.trim().toLocaleLowerCase('ko');return products.map((p,i)=>({p,i})).filter(({p,i})=>(shopCategory==='전체'||productCategories[i]===shopCategory)&&(!query||(p[0]+' '+p[1]+' '+productCategories[i]).toLocaleLowerCase('ko').includes(query)))}
function shopProductCard({p,i}){return `<article class="product"><button class="product-art" style="width:100%;padding:0;display:block" onclick="productDetail(${i})" aria-label="${p[0]} 상세 보기"><img loading="lazy" src="${productImage(i)}" alt="${p[0]} 참고 이미지"><span class="product-caption">SAMPLE COLLECTION</span></button><div class="body"><span class="eyebrow">${productCategories[i]}</span><h3 style="margin-top:5px">${p[0]}</h3><p class="sub">${p[1]}</p><div class="between"><b>30 P</b><span class="badge">주문 후 30일 수령 예정</span></div><button class="primary" onclick="productDetail(${i})">옵션 선택</button></div></article>`}
function shopResults(){const items=filteredProducts();if(items.length)return '<div class="products">'+items.map(shopProductCard).join('')+'</div>';return `<div class="shop-empty"><span aria-hidden="true">⌕</span><h3>${shopQuery.trim()?'검색 결과가 없어요.':'등록된 상품이 없어요.'}</h3><p>${shopQuery.trim()?'다른 상품명이나 색상으로 검색해보세요.':'이 카테고리의 상품은 아직 준비 중이에요.'}</p><button class="secondary" onclick="resetShopFilters()">전체 상품 보기</button></div>`}
function updateShopSearch(value){shopQuery=value;document.getElementById('shopResults').innerHTML=shopResults();document.getElementById('shopCount').textContent=filteredProducts().length+'개 상품';document.getElementById('clearShopSearch').hidden=!value}
function selectShopCategory(value){shopCategory=value;render()}
function resetShopFilters(){shopCategory='전체';shopQuery='';render()}
function clearShopSearch(){const input=document.getElementById('shopSearch');input.value='';updateShopSearch('');input.focus()}
function shop(){return `${ad()}<div class="shop-editorial"><h1>포인트몰</h1><p>취향에 맞는 한 벌. 포인트로 결제하세요.</p></div><form class="shop-search" role="search" onsubmit="event.preventDefault();updateShopSearch(document.getElementById('shopSearch').value)"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><label class="sr-only" for="shopSearch">포인트몰 상품 검색</label><input id="shopSearch" type="search" placeholder="상품명, 색상으로 검색" value="${escapeHTML(shopQuery)}" oninput="updateShopSearch(this.value)" autocomplete="off"><button id="clearShopSearch" type="button" onclick="clearShopSearch()" aria-label="검색어 지우기" ${shopQuery?'':'hidden'}>×</button></form><div class="chips shop-categories" aria-label="상품 카테고리">${shopCategories.map(c=>`<button type="button" class="${shopCategory===c?'active':''}" aria-pressed="${shopCategory===c}" onclick="selectShopCategory('${c}')">${c}</button>`).join('')}</div><div class="shop-toolbar"><span id="shopCount" role="status" aria-live="polite">${filteredProducts().length}개 상품</span><button class="bag-button" onclick="showCart()" aria-label="장바구니 ${state.cart.length}개" title="장바구니">${svg('shop')}<span class="bag-count" aria-hidden="true">${state.cart.length}</span></button></div><div id="shopResults">${shopResults()}</div><p class="footnote">상품 사진과 옵션은 쇼핑 흐름 확인을 위한 샘플입니다.<br>실제 상품 주문·배송은 아직 연결되지 않았습니다.</p>`}
function my(){return `${ad()}<div class="intro"><div><p class="eyebrow">MY WARDROBE</p><h1>나의 플레이, 나의 리워드.</h1><p class="sub">게스트 스타일러 · 이 기기에 진행 상황이 저장돼요</p></div><span style="font-size:40px">✳</span></div><div class="stats"><div class="stat">사용 가능 포인트<b>${state.points} P</b></div><div class="stat">참여한 날<b>${state.claims.length}<small> 일</small></b></div><div class="stat">클리어한 게임<b>${state.completions.length}<small> 회</small></b></div></div><section class="journey journey-wide"><h2>나의 30일 챌린지</h2><p class="sub">미참여한 날은 적립되지 않아요. 30일 참여하면 총 30P를 얻어요.</p>${calendar()}</section><section class="section"><div class="section-title"><h2>주문 내역</h2><span class="badge">${state.orders.length}건</span></div><div class="list">${state.orders.length?state.orders.map(o=>`<div class="row"><div><b>${products[o.product][0]}</b><p>${o.size} · 체험 주문 ${o.date}</p><p>수령 예정 ${o.delivery}</p></div><span class="badge">체험 접수</span></div>`).join(''):'<div class="empty">아직 주문한 상품이 없어요.<br>30P를 모아 첫 번째 옷을 골라보세요.</div>'}</div></section><section class="section"><div class="section-title"><h2>포인트 적립 내역</h2></div><div class="list">${state.claims.length?[...state.claims].reverse().map(d=>`<div class="row"><div><b>오늘의 퀘스트 완료</b><p>${d} · 일일 보상</p></div><b style="color:var(--green)">+1 P</b></div>`).join(''):'<div class="empty">오늘의 퀘스트를 완료하고 첫 1P를 받아보세요.</div>'}</div></section>`}
function render(){document.body.classList.remove('playing');if(route==='play'){if(activeGame!==null){playRound();return}route='games'}document.getElementById('topPoints').textContent=state.points+' P';document.getElementById('app').innerHTML=(/^product-[0-5]$/.test(route)?productPage(Number(route.split('-')[1])):({home,games:gamePage,shop,my,login:loginPage,signup:signupPage,'other-login':otherLoginPage,account:accountPage,terms:termsPage,privacy:privacyPage}[route]||home)())+policyLinks()+'<p class="footnote">WEAR QUEST / PREVIEW<br>기록은 현재 기기에 저장됩니다.<br><a href="https://unsplash.com/photos/j2Abvzsq8z4" target="_blank" rel="noopener">Photo by Philippe Wehrli / Unsplash</a></p>';document.getElementById('nav').innerHTML=[['home','홈'],['games','게임하기'],['shop','포인트몰'],['my','마이페이지']].map(([r,t])=>`<button class="${(route===r||(r==='shop'&&route.startsWith('product-')))?'active':''}" onclick="go('${r}')" ${(route===r||(r==='shop'&&route.startsWith('product-')))?'aria-current="page"':''}>${svg(r)}${t}</button>`).join('')}
function claim(){if(claimed())return toast('오늘은 이미 1P를 적립했어요.');if(!steps().every(Boolean))return toast('오늘의 퀘스트 3개를 완료해주세요.');state.points++;state.claims.push(today());save();render();openModal('<div class="celebrate"><div class="success-icon">✳</div><p class="eyebrow">ONE DAY, ONE POINT</p><h1>오늘의 1P가 도착했어요!</h1><p class="sub">나만의 옷장에 한 걸음 더 가까워졌어요.<br>내일도 새로운 퀘스트로 만나요.</p><div class="point-big">+1 P</div><button class="primary full" onclick="closeModal()">좋아요, 내일 또 만나요</button></div>')}
function openModal(html){document.getElementById('modalBody').innerHTML=html;const m=document.getElementById('modal');if(!m.open)m.showModal()}function closeModal(){clearInterval(timer);sessionToken++;document.getElementById('modal').close();activeGame=null}document.getElementById('modal').addEventListener('cancel',()=>{clearInterval(timer);sessionToken++;activeGame=null});
function startGame(id){clearInterval(timer);sessionToken++;document.getElementById('modal').close();activeGame=id;round=0;answering=false;route='play';history.pushState(null,'','#play');window.scrollTo(0,0);playRound()}
function gameShell(content){document.body.classList.add('playing');const g=games[activeGame];document.getElementById('app').innerHTML=`${ad()}<div class="play-toolbar"><button onclick="go('games')">← 게임 목록</button><span>WEAR QUEST / PLAY</span></div><section class="inline-play"><span class="badge">${g[4]} · 퀘스트 플레이</span><h1 style="margin-top:16px">${g[0]}</h1>${content}<div class="feedback" id="feedback" aria-live="polite"></div><p class="play-footnote">${claimed()?'오늘 1P 적립 완료 · 계속 즐길 수 있어요':'3회 클리어 + 2종 플레이 시 하루 1P 자동 적립'}</p></section>`;document.getElementById('nav').innerHTML=[['home','홈'],['games','게임하기'],['shop','포인트몰'],['my','마이페이지']].map(([r,t])=>`<button class="${r==='games'?'active':''}" onclick="go('${r}')">${svg(r)}${t}</button>`).join('')}
function playRound(){const type=games[activeGame][5];if(type==='memory')return memoryGame();if(type==='odd')return oddGame();if(type==='sequence')return sequenceGame();if(type==='timing')return timingGame();if(type==='color')return colorGame();const q=(quizBank[activeGame]||quizBank[0])[round];gameShell(`<p class="sub">${round+1} / 3 문제 · 맞는 답을 골라주세요</p><div class="game-stage"><img class="play-illustration" src="${gameIllustrations[activeGame]}" alt="${games[activeGame][0]} 일러스트"><h3>${q[0]}</h3></div><div class="answers">${q[1].map((a,i)=>`<button onclick="answer(${i},${q[2]})">${a}</button>`).join('')}</div>`)}
let answering=false;function answer(i,correct){if(answering)return;if(i!==correct){document.getElementById('feedback').textContent='아쉬워요! 다시 골라보세요.';return}answering=true;document.getElementById('feedback').textContent='정답이에요! ✓';const token=sessionToken;setTimeout(()=>{answering=false;if(token!==sessionToken)return;round++;if(round>=3)win();else playRound()},450)}
function win(){clearInterval(timer);const id=activeGame;if(id===null)return;state.completions.push({id,date:today()});const awarded=steps().every(Boolean)&&!claimed();if(awarded){state.points+=1;state.claims.push(today())}save();document.getElementById('topPoints').textContent=state.points+' P';const count=completedToday().length,distinct=new Set(completedToday().map(c=>c.id)).size;gameShell(`<div class="celebrate"><div class="success-icon">${awarded?'✳':'✓'}</div><h1>${awarded?'+1P 적립 완료!':'게임 클리어!'}</h1><p class="sub">${games[id][0]} 완료</p>${awarded?`<div class="point-big">+1 P</div><p class="sub">오늘의 미션을 모두 달성했어요.<br>보유 포인트 ${state.points}P에 자동 반영됐습니다.</p>`:claimed()?'<p class="checkout-note">오늘의 1P는 이미 적립했어요.<br>내일 다시 포인트를 받을 수 있어요.</p>':`<div class="checkout-note">1P 자동 적립까지<br>게임 클리어 <b>${Math.min(count,3)} / 3회</b> · 서로 다른 게임 <b>${Math.min(distinct,2)} / 2종</b><br>${count<3?Math.max(0,3-count)+'회 더 클리어해주세요.':''} ${distinct<2?'다른 게임도 플레이해주세요.':''}</div>`}<button class="primary full" onclick="go('games')">다음 게임 도전하기 ↗</button><button class="secondary full" onclick="go('my')">포인트 내역 보기</button></div>`);activeGame=null}
function shuffle(a){return a.map(v=>({v,n:Math.random()})).sort((a,b)=>a.n-b.n).map(x=>x.v)}
function memoryGame(){const sets={1:['👕','👖','👗','🧢'],4:['🧦','🧤','🥿','👟'],8:['👟','👞','🥾','👠'],15:['👜','🕶️','💍','🎒']};const items=shuffle([...(sets[activeGame]||sets[1]),...(sets[activeGame]||sets[1])]);gameShell('<p class="sub">카드를 뒤집어 같은 아이템 4쌍을 찾아주세요.</p><div class="game-stage"><div class="memory" id="cards"></div></div>');let open=[],matched=new Set(),locked=false;const token=sessionToken;const el=document.getElementById('cards');el.innerHTML=items.map((x,i)=>`<button data-i="${i}" aria-label="${i+1}번 카드">?</button>`).join('');el.onclick=e=>{const b=e.target.closest('button');if(!b||locked)return;let i=+b.dataset.i;if(open.includes(i)||matched.has(i))return;b.innerHTML=fashionIcon(items[i]);b.classList.add('revealed');open.push(i);if(open.length===2){const[a,c]=open;if(items[a]===items[c]){matched.add(a);matched.add(c);open=[];if(matched.size===8)setTimeout(()=>{if(token===sessionToken)win()},400)}else{locked=true;setTimeout(()=>{if(token!==sessionToken)return;open.forEach(n=>{el.children[n].textContent='?';el.children[n].classList.remove('revealed')});open=[];locked=false},700)}}}}
function oddGame(){let odd=Math.floor(Math.random()*12);const chars=activeGame===9?['▦','▤']:['👕','👚'];gameShell(`<p class="sub">${round+1} / 3 · 다른 하나를 찾아 터치하세요.</p><div class="game-stage"><div class="memory">${Array.from({length:12},(_,i)=>`<button aria-label="아이템 ${i+1}" onclick="answer(${i},${odd})">${fashionIcon(chars[i===odd?1:0])}</button>`).join('')}</div></div>`)}
function colorGame(){const qs=activeGame===12?[['네이비와 같은 푸른 계열은?',['스카이블루','오렌지','레드'],['#8ac5e6','#e98946','#bc4242'],0],['포레스트와 같은 녹색 계열은?',['핑크','올리브','퍼플'],['#e7a5c6','#858d44','#9154ab'],1],['버건디와 같은 붉은 계열은?',['블루','그린','로즈'],['#4278b8','#508b5d','#bd6a78'],2]]:[['포레스트 그린을 찾아주세요',['포레스트','코랄','네이비'],['#286647','#e88473','#243955'],0],['따뜻한 노란색을 찾아주세요',['블루','머스터드','퍼플'],['#649cc5','#d6ab42','#925caa'],1],['차가운 파란색을 찾아주세요',['레드','올리브','스카이블루'],['#c65454','#93984e','#7cbbdd'],2]];const q=qs[round];gameShell(`<p class="sub">${round+1} / 3 · 컬러 감각을 깨워보세요</p><div class="game-stage"><h3>${q[0]}</h3></div><div class="answers">${q[1].map((a,i)=>`<button onclick="answer(${i},${q[3]})"><span style="display:inline-block;vertical-align:middle;width:30px;height:30px;border-radius:50%;background:${q[2][i]};margin-right:15px"></span>${a}</button>`).join('')}</div>`)}
function sequenceGame(){const seq=shuffle(['👕','👖','👗','🧢']);let at=0;gameShell('<p class="sub">순서를 기억하세요. 3초 뒤 가려져요.</p><div class="game-stage"><div id="seq" class="sequence-icons">'+seq.map(fashionIcon).join('')+'</div></div><div class="memory" id="seqButtons"></div>');const token=sessionToken;setTimeout(()=>{if(token!==sessionToken)return;document.getElementById('seq').textContent='? → ? → ? → ?';const el=document.getElementById('seqButtons');shuffle(seq).forEach(x=>{const b=document.createElement('button');b.innerHTML=fashionIcon(x);b.onclick=()=>{if(x===seq[at]){at++;b.disabled=true;document.getElementById('feedback').textContent=at+' / 4 순서 정답';if(at===4)win()}else{document.getElementById('feedback').textContent='순서가 달라요. 다시 기억해보세요.'}};el.appendChild(b)})},3000)}
function timingGame(){let pos=0,direction=1;gameShell('<p class="sub">초록 구간(40~60)에서 멈추기! 3번 성공하면 클리어.</p><div class="game-stage"><div style="position:relative;height:28px;background:linear-gradient(90deg,#dfe4da 40%,#87bc67 40%,#87bc67 60%,#dfe4da 60%);border-radius:20px"><span id="marker" style="position:absolute;top:-4px;width:6px;height:36px;background:#1e3329;border-radius:4px;left:0"></span></div><p id="timingScore" class="sub">0 / 3 성공</p></div><button class="primary full" id="stopper">지금 멈추기</button>');timer=setInterval(()=>{pos+=direction*2;if(pos>=98||pos<=0)direction*=-1;document.getElementById('marker').style.left=pos+'%'},25);document.getElementById('stopper').onclick=()=>{if(pos>=40&&pos<=60){round++;if(round>=3)return win();document.getElementById('timingScore').textContent=round+' / 3 성공';document.getElementById('feedback').textContent='정확해요! 다음 타이밍도 도전.';pos=0}else document.getElementById('feedback').textContent='조금 더 정확하게! 다시 도전하세요.'}}
function deliveryDate(){let d=new Date(today()+'T12:00:00+09:00');d.setUTCDate(d.getUTCDate()+30);return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
function productDetail(i){if(!Number.isInteger(i)||!products[i])return;go('product-'+i)}
function productPage(i){const p=products[i];return `${ad()}<section class="product-page"><div class="product-page-toolbar"><button class="text-button" onclick="go('shop')">← 포인트몰</button><button class="bag-button" onclick="showCart()" aria-label="장바구니 ${state.cart.length}개">${svg('shop')}<span class="bag-count" aria-hidden="true">${state.cart.length}</span></button></div><img class="product-photo" src="${productImage(i)}" alt="${p[0]} 참고 이미지"><div class="detail-brand">WEAR QUEST ESSENTIALS</div><h1>${p[0]}</h1><p class="sub">${p[1]}</p><div class="product-price">30 P</div><div class="purchase-info"><span>결제 방법</span><span>보유 포인트 전액 결제</span><span>수령 예정</span><span>주문일로부터 30일 후</span><span>배송비</span><span>무료 (샘플 정책)</span></div><div class="form-grid"><div><label for="color">컬러</label><select id="color"><option>${p[1].split(' · ')[0]}</option></select></div><div><label for="size">사이즈</label><select id="size"><option value="">선택해주세요</option>${(i===2?['FREE']:['S','M','L','XL']).map(x=>'<option>'+x+'</option>').join('')}</select></div></div><p class="size-guide">샘플 상품입니다. 실제 소재·실측·재고는 상품 등록 시 제공됩니다.</p><div class="detail-actions"><button class="secondary" onclick="addToCart(${i},false)">장바구니 담기</button><button class="primary" onclick="addToCart(${i},true)">바로 구매</button></div><p class="sub" style="font-size:12px">현재 보유 ${state.points}P · 실제 주문 미연결</p></section>`}
function addToCart(i,buy){const size=document.getElementById('size').value;if(!size)return toast('사이즈를 선택해주세요.');const color=document.getElementById('color').value;state.cart.push({product:i,size,color});save();if(buy)showCart();else{closeModal();render();toast('장바구니에 담았어요.')}}
function removeCart(i){state.cart.splice(i,1);save();render();showCart()}
function showCart(){const total=state.cart.length*30;openModal(`<span class="eyebrow">SHOPPING BAG</span><h2 style="margin-top:10px">장바구니 <small>(${state.cart.length})</small></h2>${state.cart.length?state.cart.map((x,i)=>`<div class="cart-item"><img src="${productImage(x.product)}" alt="${products[x.product][0]}"><div><h3>${products[x.product][0]}</h3><p>${x.color} / ${x.size} / 1개</p><div class="between"><b>30 P</b><button onclick="removeCart(${i})">삭제</button></div></div></div>`).join(''):'<div class="empty">장바구니가 비어 있어요.<br>마음에 드는 옷을 골라보세요.</div>'}<div class="summary-line"><span>보유 포인트</span><b>${state.points} P</b></div><div class="summary-line total"><span>총 결제 포인트</span><b>${total} P</b></div>${state.cart.length?'<button class="primary full" onclick="checkout()">주문서 작성</button>':''}<p class="sub" style="font-size:12px">${total>state.points?(total-state.points)+'P가 부족해요. 주문서 확인은 가능하며 결제는 포인트를 모은 뒤 할 수 있어요.':'배송비 무료 · 주문일로부터 30일 후 수령 예정'}</p>`)}
function checkout(){if(!state.cart.length)return;const total=state.cart.length*30;openModal(`<span class="eyebrow">CHECKOUT</span><h2 style="margin-top:10px">주문 / 포인트 결제</h2><p class="checkout-note">현재는 주문 흐름 체험 화면입니다. 실제 주문은 전송되지 않습니다. 실제 개인정보 대신 테스트 정보를 입력해주세요.</p><form id="checkoutForm"><label for="recipient">받는 분</label><input id="recipient" name="recipient" placeholder="테스트 고객" required maxlength="40" autocomplete="off"><label for="phone">연락처</label><input id="phone" name="phone" type="tel" placeholder="010-0000-0000" required pattern="[0-9+() -]{9,20}" autocomplete="off"><label for="address">배송 주소</label><input id="address" name="address" placeholder="테스트 배송 주소" required minlength="5" maxlength="180" autocomplete="off"><label for="detailAddress">상세 주소</label><input id="detailAddress" name="detailAddress" placeholder="동 / 호수 (선택)" maxlength="100" autocomplete="off"><label for="memo">배송 요청사항</label><select id="memo"><option>문 앞에 놓아주세요</option><option>배송 전 연락해주세요</option><option>직접 받을게요</option></select><div class="summary-line" style="margin-top:24px"><span>주문 상품</span><b>${state.cart.length}개</b></div><div class="summary-line"><span>보유 포인트</span><b>${state.points} P</b></div><div class="summary-line total"><span>총 결제</span><b>${total} P</b></div><div class="summary-line"><span>결제 후 잔액</span><b>${Math.max(0,state.points-total)} P</b></div><p class="sub">수령 예정일 ${deliveryDate()} · 주문일 +30일</p><label class="check-label"><input type="checkbox" required><span>상품 옵션과 포인트 차감 금액을 확인했으며, 실제 배송되지 않는 체험 주문에 동의합니다.</span></label><button class="primary full" type="submit" ${state.points<total?'disabled':''}>${state.points<total?(total-state.points)+'P 부족 · 퀘스트로 모으기':total+'P로 체험 결제'}</button></form>`);document.getElementById('checkoutForm').onsubmit=e=>{e.preventDefault();placeOrder()}}
function placeOrder(){const total=state.cart.length*30;if(!total||state.points<total)return;const form=document.getElementById('checkoutForm');if(!form||!form.reportValidity())return;state.points-=total;const orderId='WQ-'+Date.now().toString(36).toUpperCase();state.cart.forEach(x=>state.orders.unshift({product:x.product,size:x.size,color:x.color,date:today(),delivery:deliveryDate(),orderId}));state.cart=[];save();render();openModal(`<div class="celebrate"><div class="success-icon">✓</div><span class="eyebrow">ORDER COMPLETED</span><h2>체험 주문이 완료됐어요.</h2><p class="sub">주문번호 ${orderId}<br>결제 ${total}P · 수령 예정 ${deliveryDate()}</p><p class="checkout-note">실제 주문·배송은 발생하지 않았습니다.<br>입력한 배송지 정보는 저장하거나 전송하지 않습니다.</p><button class="primary full" onclick="closeModal();go('my')">주문 내역 확인</button></div>`)}
route=location.hash.slice(1)||'home';render();


function policyLinks(){return `<footer class="policy-links" aria-label="서비스 정책"><button type="button" onclick="go('terms')">이용약관</button><span aria-hidden="true">|</span><button type="button" onclick="go('privacy')">개인정보 처리방침</button></footer>`}
function termsPage(){return `<article class="policy-page"><button class="text-button" onclick="go('home')">← 홈으로</button><span class="eyebrow">TERMS OF SERVICE</span><h1>이용약관</h1><p class="policy-draft">정식 약관 게시 준비 중</p><p>현재는 서비스의 화면과 기능을 확인하는 체험 버전입니다. 아래는 현재 체험 기능에 대한 안내이며, 정식 이용약관은 아닙니다.</p><h2>체험 서비스</h2><p>패션 게임, 일일 미션, 포인트 적립 및 상품 주문 흐름을 체험할 수 있습니다.</p><h2>포인트 적립</h2><p>서로 다른 게임 2종을 포함하여 하루 총 3회 클리어하면 1P가 자동 적립됩니다. 하루 최대 적립량은 1P이며, 날짜는 한국시간을 기준으로 합니다.</p><h2>상품과 주문</h2><p>등록된 상품은 샘플입니다. 포인트 결제는 체험용이며 실제 상품 주문과 배송은 진행되지 않습니다.</p><h2>정식 서비스 안내</h2><p>운영자 정보와 정식 서비스의 이용 조건·포인트 정책·주문 및 취소 정책은 서비스 오픈 전에 게시할 예정입니다.</p></article>`}
function privacyPage(){return `<article class="policy-page"><button class="text-button" onclick="go('home')">← 홈으로</button><span class="eyebrow">PRIVACY POLICY</span><h1>개인정보 처리방침</h1><p class="policy-draft">정식 처리방침 게시 준비 중</p><p>아래는 현재 체험 웹앱의 기록 저장 방식에 대한 안내입니다. 정식 개인정보 처리방침은 운영 주체와 실제 데이터 처리 구성이 확정된 뒤 게시할 예정입니다.</p><h2>현재 기기에 저장되는 기록</h2><p>게임 완료 기록, 포인트 잔액과 적립 날짜, 장바구니, 체험 주문의 상품 및 옵션 정보가 브라우저의 로컬 저장소에 저장됩니다. 계정이나 다른 기기와 동기화되지 않습니다.</p><h2>배송지 입력</h2><p>체험 주문서에 입력한 이름·연락처·주소는 앱에서 저장하거나 주문 서버로 전송하지 않습니다. 실제 개인정보 대신 테스트 정보를 입력해주세요.</p><h2>기록 삭제</h2><p>브라우저 설정에서 이 사이트의 저장된 데이터를 삭제하면 기기에 저장된 진행 기록도 함께 삭제됩니다. 삭제한 체험 기록은 앱에서 복구할 수 없습니다.</p><h2>정식 방침 안내</h2><p>실제 로그인·주문·광고 서비스 연결 시 운영자 및 문의처, 수집 항목과 목적, 보관 기간, 외부 서비스 이용 등 확정된 처리 내용을 반영할 예정입니다.</p></article>`}

initializeAuth();
